import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, MAX_ATTEMPTS, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;

const db = openDatabase();
let stopping = false;

const beatStmt = db.prepare(
  'INSERT INTO heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
);
function beat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}

// Recover jobs left running by a worker that died. The interrupted attempt is retried; if it was
// already the last allowed attempt, it is re-run as that attempt rather than exceeding the limit.
const now = () => new Date().toISOString();
db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, next_run_at = 0, updated_at = ?,
     attempts = CASE WHEN attempts >= ? THEN ? ELSE attempts END
   WHERE status = 'running'`,
).run(now(), MAX_ATTEMPTS, MAX_ATTEMPTS - 1);

const pickStmt = db.prepare(
  `SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1`,
);
const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ?
   WHERE id = ? AND status = 'queued'`,
);
const progressStmt = db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', progress = ?, output = ?, error = NULL, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const retryStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, next_run_at = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const failStmt = db.prepare(
  `UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const getStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');

function claimNext(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = pickStmt.get(Date.now()) as JobRow | undefined;
    if (row) claimStmt.run(now(), row.id);
    db.exec('COMMIT');
    return row ? (getStmt.get(row.id) as unknown as JobRow) : undefined;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  console.log(`job ${job.id}: attempt ${attempt}`);
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // left as running; recovered on next start
    if (step === 1 && attempt <= job.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) {
        failStmt.run('transient failure', now(), job.id);
        console.log(`job ${job.id}: failed`);
      } else {
        retryStmt.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
