  `UPDATE jobs SET status = 'queued', progress = 0, next_run_at = 0, updated_at = ?,
     attempts = CASE WHEN attempts >= ? THEN ? ELSE attempts END
   WHERE status = 'running'`,
).run(now(), MAX_ATTEMPTS, MAX_ATTEMPTS - 1);

