import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

type FieldError = { field: string; message: string };

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store',
    ...headers,
  });
  res.end(data);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  else if (err.code === 'invalid_request') error.fields = [];
  send(res, err.status, { error }, err.status === 405 ? {} : {});
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooBig = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooBig = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve(tooBig ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function validate(contentType: string | undefined, raw: string | null, key: string | undefined): Payload {
  const errors: FieldError[] = [];
  if (key !== undefined && !KEY_RE.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }
  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    errors.push({ field: 'Content-Type', message: 'must be application/json' });
    errors.push({ field: 'body', message: 'request body must be sent as application/json' });
    throw new HttpError(400, 'invalid_request', 'Content-Type must be application/json.', errors);
  }
  if (raw === null) {
    errors.push({ field: 'body', message: 'body is too large' });
    throw new HttpError(400, 'invalid_request', 'Request body is too large.', errors);
  }
  let body: unknown;
  try {
    body = JSON.parse(raw);
  } catch {
    errors.push({ field: 'body', message: 'body must be valid JSON' });
    throw new HttpError(400, 'invalid_request', 'Request body is not valid JSON.', errors);
  }
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    errors.push({ field: 'body', message: 'body must be a JSON object' });
    throw new HttpError(400, 'invalid_request', 'Request body must be a JSON object.', errors);
  }
  const obj = body as Record<string, unknown>;
  for (const k of Object.keys(obj)) {
    if (k !== 'input' && k !== 'steps' && k !== 'failAttempts') errors.push({ field: k, message: 'unknown field' });
  }
  const input = obj.input;
  if (!Object.hasOwn(obj, 'input')) errors.push({ field: 'input', message: 'is required' });
  else if (typeof input !== 'string') errors.push({ field: 'input', message: 'must be a string' });
  else if (input.length < 1 || input.length > 1000) errors.push({ field: 'input', message: 'must be 1-1000 characters' });
  else if (input.trim() === '') errors.push({ field: 'input', message: 'must not be only whitespace' });

  const intField = (name: string, min: number, max: number, def: number): number => {
    if (!Object.hasOwn(obj, name)) return def;
    const v = obj[name];
    if (typeof v !== 'number' || !Number.isInteger(v)) {
      errors.push({ field: name, message: 'must be an integer' });
      return def;
    }
    if (v < min || v > max) errors.push({ field: name, message: `must be between ${min} and ${max}` });
    return v;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);
  if (errors.length) throw new HttpError(400, 'invalid_request', 'The request is invalid.', errors);
  return { input: input as string, steps, failAttempts };
}

const insertStmt = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, idempotency_key, payload, next_run_at, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const byKeyStmt = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const byIdStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const listStmt = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const beatStmt = db.prepare('SELECT beat_at FROM heartbeat WHERE id = 1');

function createJob(p: Payload, key: string | undefined): { status: number; job: ReturnType<typeof toJob> } {
  const payload = JSON.stringify([p.input, p.steps, p.failAttempts]);
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = byKeyStmt.get(key) as (JobRow & { payload: string }) | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload === payload) return { status: 200, job: toJob(existing) };
        throw new HttpError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    const ts = new Date().toISOString();
    insertStmt.run(id, p.input, p.steps, p.failAttempts, key ?? null, payload, ts, ts);
    db.exec('COMMIT');
    return { status: 201, job: toJob(byIdStmt.get(id) as unknown as JobRow) };
  } catch (err) {
    if (db.isTransaction) db.exec('ROLLBACK');
    throw err;
  }
}

function methodNotAllowed(allowed: string): HttpError {
  return new HttpError(405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed}.`);
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET' && method !== 'HEAD') throw methodNotAllowed('GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') throw methodNotAllowed('GET');
    const row = beatStmt.get() as { beat_at: number } | undefined;
    const up = row !== undefined && Date.now() - row.beat_at <= 3000;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = listStmt.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') {
      const raw = await readBody(req);
      const keyHeader = req.headers['idempotency-key'];
      const key = Array.isArray(keyHeader) ? keyHeader.join(',') : keyHeader;
      const payload = validate(req.headers['content-type'], raw, key);
      const { status, job } = createJob(payload, key);
      return send(res, status, job);
    }
    throw methodNotAllowed('GET, POST');
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (method !== 'GET') throw methodNotAllowed('GET');
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = byIdStmt.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) return void res.end();
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

